onRoleReachedMoon = function()    game.pauseLogic()	if global.isLevelPassed(43) and global.isLevelPassed(45) then		if global.getBool("stg_b3") then dialog.setSkipEnabled(true) end		repeat			sound.play("54-1")			if dialog.show("Stage3F-1", faceManyi) ==1 then break end			if dialog.show("Stage3F-2", faceBujie) ==1 then break end			if dialog.show("Stage3F-3", facePutong) ==1 then break end			if dialog.show("Stage3F-4", faceZhoumei) ==1 then break end			if dialog.show("Stage3F-5", faceShengqi) ==1 then break end			sound.play("58-1")			global.setBool("stg_b3")		until true		dialog.setSkipEnabled(false)    end    game.success()end